style.css:
@-moz-document domain("youtube.com") {
/* Bonzi image in the corner */
    body::after {
        content: "";
        position: fixed;
        bottom: 0;
        right: 0;
        width: 150px;
        height: 200px;
        background-image: url("https://i.imgur.com/YOYZaMZ.png");
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 999999;
        pointer-events: none;
        opacity: 0.95;
        filter: saturate(1.3) contrast(1.2) drop-shadow(0 0 8px red);
    }

    /* Mean warning banner */
    #masthead-container::before {
        content: "? Bonzi Buddy is watching your every move...";
        display: block;
        background-color: #8B0000;
        color: white;
        font-weight: bold;
        font-family: sans-serif;
        padding: 8px;
        text-align: center;
        font-size: 14px;
        box-shadow: 0 2px 8px rgba(0,0,0,0.5);
        z-index: 9999;
    }

    /* Make background a little sus-looking */
    body {
        background-color: #1a0000 !important;
    }

    /* Optional: make video titles spooky */
    ytd-video-renderer #video-title {
        color: #ff5555 !important;
        text-shadow: 1px 1px 2px black;
    }
}
